#include<bits/stdc++.h>
using namespace std;
int n,q;
int a[20005],b[4];
bool check(vector<int> x,int y,int z){
    int num=0;
    for(int i=y;i<=z;i++)
        num+=x[i];
    return (num==4||num==8);
}
bool dfs(vector<pair<int,int> > x,vector<int> y){
    if(y.empty()){
        cout<<"Yes\n"<<x.size()<<'\n';
        for(auto i:x){
            cout<<i.first<<' '<<i.second<<'\n';
        }
        return 1;
    }
    for(int i=1;i<n;i++){
        for(int j=i+1;j<=n;j++){
            if(check(y,i-1,j-1)){
                vector<pair<int,int> > xx=x;
                vector<int> yy=y;
                xx.push_back({i,j});
                yy.erase(yy.begin()+i-1,yy.begin()+j);
                if(dfs(xx,yy))
                    return 1;
            }
        }
    }
    return 0;
}
signed main(){
    ios::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    cin>>n>>q;
    for(int i=1;i<=n;i++){
        int x;
        cin>>x;
        a[i]=x;
        b[x]++;
    }
    for(int i=1;i<=q;i++){
        int k;
        cin>>k;
        if(k==1){
            int p,x;
            cin>>p>>x;
            b[a[p]]--;
            b[x]++;
            a[p]=x;
        }
        else if(k==2){
            int x,y;
            x=b[1]+b[3];
            y=b[2]+b[3];
            y%=4;y%=2;
            if(!(2*y+x==4||2*y+x==8))
                cout<<"No\n";
            else
                cout<<"Yes\n";
        }
        else if(k==3){
            vector<pair<int,int> > u;
            vector<int> v;
            for(int i=1;i<=n;i++){
                v.push_back(a[i]);
            }
            dfs(u,v);
        }
    }
    return 0;
}
